/**
 * Bot levels (PRD §3.1). Pure: the caller passes the solved table and a random
 * source. Hard and Impossible may choose a deliberate timeout ('timeout'), which
 * the caller plays by letting the clock run out.
 */
import { applyMove, applyTimeout, legalMoves } from './round.ts';
import { decodeValue, encodePosition, positionOf, shapeOf } from './table.ts';
import type { RoundState } from './types.ts';

export type BotLevel = 'easy' | 'medium' | 'hard' | 'impossible';
export type BotAction = number | 'timeout';

export const BOT_LEVELS: readonly BotLevel[] = ['easy', 'medium', 'hard', 'impossible'];

export interface ScoredAction {
  action: BotAction;
  /** Higher is better for the bot: fast wins high, draws 0, slow losses less negative. */
  score: number;
}

/** Score of a result for the player who just acted. */
function scoreAfter(round: RoundState, next: RoundState, table: Uint8Array): number {
  const me = round.toMove;
  if (next.status === 'won') return next.winner === me ? 1000 - 1 : -1000 + 1;
  if (next.status === 'draw') return 0;
  const v = decodeValue(table[encodePosition(shapeOf(next.config), positionOf(next))]!);
  // v is from the opponent's side (they move next).
  if (v.kind === 'win') return -1000 + (v.plies + 1);
  if (v.kind === 'loss') return 1000 - (v.plies + 1);
  return 0;
}

/** Every legal action scored with perfect play from the table. */
export function scoreActions(round: RoundState, table: Uint8Array, allowTimeout = true): ScoredAction[] {
  const out: ScoredAction[] = legalMoves(round).map((c) => ({ action: c, score: scoreAfter(round, applyMove(round, c), table) }));
  if (allowTimeout) out.push({ action: 'timeout', score: scoreAfter(round, applyTimeout(round), table) });
  return out;
}

function pick<T>(xs: readonly T[], rand: () => number): T {
  return xs[Math.floor(rand() * xs.length)]!;
}

function best(scored: ScoredAction[], rand: () => number): BotAction {
  const top = Math.max(...scored.map((s) => s.score));
  return pick(
    scored.filter((s) => s.score === top),
    rand,
  ).action;
}

function secondBest(scored: ScoredAction[], rand: () => number): BotAction {
  const levels = [...new Set(scored.map((s) => s.score))].sort((a, b) => b - a);
  const target = levels[1] ?? levels[0]!;
  return pick(
    scored.filter((s) => s.score === target),
    rand,
  ).action;
}

/** Cells where `round.toMove`'s placement would complete a line right now. */
function winningCells(round: RoundState): number[] {
  return legalMoves(round).filter((c) => {
    const n = applyMove(round, c);
    return n.status === 'won';
  });
}

/** Medium: 2-ply with noise. Always takes a win in one, sometimes misses a block. */
function medium(round: RoundState, rand: () => number): BotAction {
  const wins = winningCells(round);
  if (wins.length) return pick(wins, rand);
  const moves = legalMoves(round);
  // Moves after which the opponent has no immediate win.
  const safe = moves.filter((c) => winningCells(applyMove(round, c)).length === 0);
  if (safe.length && rand() < 0.75) return pick(safe, rand);
  return pick(moves, rand);
}

export function chooseBotAction(round: RoundState, level: BotLevel, table: Uint8Array, rand: () => number): BotAction {
  const moves = legalMoves(round);
  if (moves.length === 0) throw new RangeError('no legal moves');
  switch (level) {
    case 'easy': {
      if (rand() < 0.7) return pick(moves, rand);
      return best(scoreActions(round, table, false), rand);
    }
    case 'medium':
      return medium(round, rand);
    case 'hard': {
      const scored = scoreActions(round, table);
      return rand() < 0.1 ? secondBest(scored, rand) : best(scored, rand);
    }
    case 'impossible':
      return best(scoreActions(round, table), rand);
  }
}

/** Human-like think time in ms, always well inside the clock. */
export function botThinkMs(clockMs: number, rand: () => number): number {
  const [lo, hi] = clockMs <= 3000 ? [300, 900] : [400, 1500];
  return Math.min(lo + rand() * (hi - lo), clockMs * 0.6);
}

/** Bot reaction in the start race (ms after GO). */
export function botReactionMs(level: BotLevel, rand: () => number): number {
  const base = { easy: 420, medium: 360, hard: 300, impossible: 260 }[level];
  return base + rand() * 160;
}
